<?php require_once __DIR__.'/../includes/tutor_auth_check.php';require_once __DIR__.'/../config/db.php';$rows=[];$total=0;try{$p=db();$q=$p->prepare('SELECT id FROM tutors WHERE user_id=?');$q->execute([$_SESSION['user_id']]);$id=$q->fetchColumn();$q=$p->prepare("SELECT p.*,b.booking_date FROM payments p JOIN bookings b ON b.id=p.booking_id WHERE b.tutor_id=? AND p.status='success' ORDER BY p.created_at DESC");$q->execute([$id]);$rows=$q->fetchAll();$total=array_sum(array_column($rows,'amount'));}catch(Throwable $e){}$pageTitle='Earnings';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';?><main class="container py-5"><h1 class="h2">Earnings</h1><div class="profile-section mb-3">Lifetime earnings <strong>৳<?=number_format($total,2)?></strong></div><table class="table"><tr><th>Date</th><th>Amount</th><th>Method</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td>৳<?=e($r['amount'])?></td><td><?=e($r['method'])?></td></tr><?php endforeach;?></table></main><?php require __DIR__.'/../includes/footer.php';?>
